import {
  Component,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Input,
  Output,
  EventEmitter,
  ElementRef,
  OnInit,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MatIconModule } from '@angular/material/icon';
import { MatButtonModule } from '@angular/material/button';
import { MatTooltipModule } from '@angular/material/tooltip';
import { CalendarEvent, EventResponseStatus } from '../../models/event.model';
import { Calendar } from '../../models/calendar.model';
import { format } from 'date-fns';
import { ja } from 'date-fns/locale';

@Component({
  selector: 'app-event-detail',
  standalone: true,
  imports: [CommonModule, FormsModule, MatIconModule, MatButtonModule, MatTooltipModule],
  templateUrl: './event-detail.component.html',
  styleUrls: ['./event-detail.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class EventDetailComponent implements OnInit {
  @Input({ required: true }) event!: CalendarEvent;
  @Input() calendar?: Calendar;
  @Input() anchorEl?: HTMLElement;

  @Output() editClicked = new EventEmitter<CalendarEvent>();
  @Output() deleteClicked = new EventEmitter<CalendarEvent>();
  @Output() duplicateClicked = new EventEmitter<CalendarEvent>();
  @Output() responseChanged = new EventEmitter<{ event: CalendarEvent; response: EventResponseStatus }>();
  @Output() guestsInvited = new EventEmitter<{ event: CalendarEvent; emails: string[] }>();
  @Output() closed = new EventEmitter<void>();

  showFullDescription = false;

  /** メール招待 (ユーザー指示 2026-04-21) */
  inviteEmailInput = '';
  inviteError = '';

  constructor(private cdr: ChangeDetectorRef) {}

  ngOnInit(): void {}

  get eventColor(): string {
    return this.calendar?.color || this.event.color || '#1976d2';
  }

  get dateTimeDisplay(): string {
    if (this.event.allDay) {
      const startStr = format(this.event.start, 'M月d日 (EEEE)', { locale: ja });
      if (this.event.end.getTime() - this.event.start.getTime() > 86400000) {
        const endStr = format(
          new Date(this.event.end.getTime() - 86400000),
          'M月d日 (EEEE)',
          { locale: ja }
        );
        return `${startStr} - ${endStr} (終日)`;
      }
      return `${startStr} (終日)`;
    }
    const startDate = format(this.event.start, 'M月d日 (EEEE)', { locale: ja });
    const startTime = format(this.event.start, 'H:mm');
    const endTime = format(this.event.end, 'H:mm');
    return `${startDate} ${startTime} - ${endTime}`;
  }

  get recurrenceDisplay(): string {
    if (!this.event.recurrence) return '';
    const r = this.event.recurrence;
    switch (r.frequency) {
      case 'daily':
        return r.interval === 1 ? '毎日' : `${r.interval}日ごと`;
      case 'weekly': {
        const dayMap: Record<string, string> = {
          MO: '月',
          TU: '火',
          WE: '水',
          TH: '木',
          FR: '金',
          SA: '土',
          SU: '日',
        };
        const days = r.byDay?.map(d => dayMap[d] || d).join('、') || '';
        return r.interval === 1
          ? `毎週 ${days}`
          : `${r.interval}週間ごと ${days}`;
      }
      case 'monthly':
        return r.interval === 1 ? '毎月' : `${r.interval}ヶ月ごと`;
      case 'yearly':
        return '毎年';
      default:
        return '';
    }
  }

  get truncatedDescription(): string {
    if (!this.event.description) return '';
    if (this.showFullDescription) return this.event.description;
    const lines = this.event.description.split('\n');
    if (lines.length <= 3 && this.event.description.length <= 150) {
      return this.event.description;
    }
    return lines.slice(0, 3).join('\n').substring(0, 150) + '...';
  }

  get hasMoreDescription(): boolean {
    if (!this.event.description) return false;
    const lines = this.event.description.split('\n');
    return lines.length > 3 || this.event.description.length > 150;
  }

  getResponseIcon(status: EventResponseStatus): string {
    switch (status) {
      case 'accepted':
        return 'check_circle';
      case 'declined':
        return 'cancel';
      case 'tentative':
        return 'help';
      case 'needsAction':
        return 'radio_button_unchecked';
    }
  }

  getResponseColor(status: EventResponseStatus): string {
    switch (status) {
      case 'accepted':
        return '#4caf50';
      case 'declined':
        return '#f44336';
      case 'tentative':
        return '#ff9800';
      case 'needsAction':
        return '#9e9e9e';
    }
  }

  onEdit(): void {
    this.editClicked.emit(this.event);
  }

  onDelete(): void {
    this.deleteClicked.emit(this.event);
  }

  onClose(): void {
    this.closed.emit();
  }

  onRespond(response: EventResponseStatus): void {
    this.responseChanged.emit({ event: this.event, response });
  }

  toggleDescription(): void {
    this.showFullDescription = !this.showFullDescription;
  }

  onNotifyByEmail(): void {
    // Mock: would send email notification
  }

  onDuplicate(): void {
    this.duplicateClicked.emit(this.event);
  }

  /** メール招待 送信 (ユーザー指示 2026-04-21) */
  onInvite(inputEl?: HTMLInputElement): void {
    const raw = (this.inviteEmailInput || '').trim();
    if (!raw) {
      this.inviteError = 'メールアドレスを入力してください';
      return;
    }
    const emails = raw
      .split(/[,、\s]+/)
      .map(s => s.trim())
      .filter(s => s.length > 0);
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const invalid = emails.filter(e => !emailRegex.test(e));
    if (invalid.length > 0) {
      this.inviteError = `不正なメールアドレス: ${invalid.join(', ')}`;
      return;
    }
    const existing = new Set(this.event.guests.map(g => g.email.toLowerCase()));
    const unique = emails.filter(e => !existing.has(e.toLowerCase()));
    if (unique.length === 0) {
      this.inviteError = '既に招待済みです';
      return;
    }
    this.inviteError = '';
    this.guestsInvited.emit({ event: this.event, emails: unique });
    this.inviteEmailInput = '';
    if (inputEl) {
      inputEl.value = '';
    }
    this.cdr.markForCheck();
  }
}
