import {
  Component,
  ChangeDetectionStrategy,
  Input,
  Output,
  EventEmitter,
  OnInit,
  ChangeDetectorRef,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MatChipsModule } from '@angular/material/chips';
import { MatIconModule } from '@angular/material/icon';
import { MatAutocompleteModule } from '@angular/material/autocomplete';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { EventGuest, EventResponseStatus } from '../../models/event.model';
import { CalendarService } from '../../services/calendar.service';
import { Subject, debounceTime, switchMap, takeUntil } from 'rxjs';

@Component({
  selector: 'app-guest-picker',
  standalone: true,
  imports: [
    CommonModule,
    FormsModule,
    MatChipsModule,
    MatIconModule,
    MatAutocompleteModule,
    MatFormFieldModule,
    MatInputModule,
  ],
  templateUrl: './guest-picker.component.html',
  styleUrls: ['./guest-picker.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class GuestPickerComponent implements OnInit {
  @Input() guests: EventGuest[] = [];
  @Output() guestsChange = new EventEmitter<EventGuest[]>();

  searchQuery = '';
  suggestions: { email: string; displayName: string }[] = [];
  private searchSubject = new Subject<string>();
  private destroy$ = new Subject<void>();

  constructor(
    private calendarService: CalendarService,
    private cdr: ChangeDetectorRef
  ) {}

  ngOnInit(): void {
    this.searchSubject
      .pipe(
        debounceTime(200),
        switchMap(query => this.calendarService.searchContacts(query)),
        takeUntil(this.destroy$)
      )
      .subscribe(results => {
        this.suggestions = results.filter(
          r => !this.guests.some(g => g.email === r.email)
        );
        this.cdr.markForCheck();
      });
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  onSearchInput(): void {
    this.searchSubject.next(this.searchQuery);
  }

  addGuest(suggestion: { email: string; displayName: string }): void {
    const guest: EventGuest = {
      email: suggestion.email,
      displayName: suggestion.displayName,
      responseStatus: 'needsAction',
    };
    this.guests = [...this.guests, guest];
    this.guestsChange.emit(this.guests);
    this.searchQuery = '';
    this.suggestions = [];
  }

  addGuestByEmail(): void {
    if (!this.searchQuery || !this.searchQuery.includes('@')) return;
    const email = this.searchQuery.trim();
    if (this.guests.some(g => g.email === email)) return;
    const guest: EventGuest = {
      email,
      displayName: email.split('@')[0],
      responseStatus: 'needsAction',
    };
    this.guests = [...this.guests, guest];
    this.guestsChange.emit(this.guests);
    this.searchQuery = '';
    this.suggestions = [];
  }

  removeGuest(guest: EventGuest): void {
    this.guests = this.guests.filter(g => g.email !== guest.email);
    this.guestsChange.emit(this.guests);
  }

  getResponseIcon(status: EventResponseStatus): string {
    switch (status) {
      case 'accepted': return 'check_circle';
      case 'declined': return 'cancel';
      case 'tentative': return 'help';
      case 'needsAction': return 'radio_button_unchecked';
    }
  }

  getResponseColor(status: EventResponseStatus): string {
    switch (status) {
      case 'accepted': return '#4caf50';
      case 'declined': return '#f44336';
      case 'tentative': return '#ff9800';
      case 'needsAction': return '#9e9e9e';
    }
  }

  displayFn(value: { email: string; displayName: string }): string {
    return value ? value.displayName : '';
  }
}
