import {
  Component,
  ChangeDetectionStrategy,
  Input,
  Output,
  EventEmitter,
  OnChanges,
  OnInit,
  OnDestroy,
  SimpleChanges,
  ViewChild,
  ElementRef,
  AfterViewInit,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { CalendarEvent } from '../../models/event.model';
import { Calendar } from '../../models/calendar.model';
import {
  isSameDay,
  format,
  startOfDay,
  endOfDay,
  areIntervalsOverlapping,
  isToday,
} from 'date-fns';
import { ja } from 'date-fns/locale';

interface PositionedEvent {
  event: CalendarEvent;
  top: number;
  height: number;
  left: number;
  width: number;
  color: string;
}

@Component({
  selector: 'app-calendar-day-view',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './calendar-day-view.component.html',
  styleUrls: ['./calendar-day-view.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CalendarDayViewComponent implements OnChanges, OnInit, OnDestroy, AfterViewInit {
  @Input({ required: true }) currentDate!: Date;
  @Input() events: CalendarEvent[] = [];
  @Input() visibleCalendarIds: string[] = [];
  @Input() calendars: Calendar[] = [];

  @Output() eventClicked = new EventEmitter<CalendarEvent>();
  @Output() timeSlotClicked = new EventEmitter<{ date: Date; hour: number; minute: number }>();

  @ViewChild('timeGrid') timeGridRef!: ElementRef<HTMLDivElement>;

  hours: number[] = [];
  allDayEvents: CalendarEvent[] = [];
  timedEvents: PositionedEvent[] = [];
  currentTimeTop = 0;
  currentTimeVisible = false;
  dayLabel = '';
  dayOfWeek = '';
  dayIsToday = false;

  private timerInterval: ReturnType<typeof setInterval> | null = null;
  private readonly hourHeight = 60;

  ngOnInit(): void {
    this.hours = [];
    for (let h = 0; h < 24; h++) {
      this.hours.push(h);
    }
    this.updateCurrentTime();
    this.timerInterval = setInterval(() => this.updateCurrentTime(), 60000);
  }

  ngAfterViewInit(): void {
    setTimeout(() => {
      if (this.timeGridRef) {
        this.timeGridRef.nativeElement.scrollTop = 7 * this.hourHeight;
      }
    }, 0);
  }

  ngOnDestroy(): void {
    if (this.timerInterval) {
      clearInterval(this.timerInterval);
    }
  }

  ngOnChanges(changes: SimpleChanges): void {
    this.buildDay();
    this.updateCurrentTime();
  }

  private updateCurrentTime(): void {
    const now = new Date();
    const minutesSinceMidnight = now.getHours() * 60 + now.getMinutes();
    this.currentTimeTop = (minutesSinceMidnight / 60) * this.hourHeight;
    this.currentTimeVisible = isSameDay(this.currentDate, now);
  }

  private buildDay(): void {
    if (!this.currentDate) return;

    this.dayLabel = format(this.currentDate, 'd', { locale: ja });
    this.dayOfWeek = format(this.currentDate, 'EEEE', { locale: ja });
    this.dayIsToday = isToday(this.currentDate);

    const dayStart = startOfDay(this.currentDate);
    const dayEnd = endOfDay(this.currentDate);

    const filtered = this.events.filter(
      e =>
        this.visibleCalendarIds.includes(e.calendarId) &&
        areIntervalsOverlapping(
          { start: e.start, end: e.end },
          { start: dayStart, end: dayEnd }
        )
    );

    this.allDayEvents = filtered.filter(e => e.allDay);
    const timed = filtered.filter(e => !e.allDay);

    this.timedEvents = this.positionEvents(timed);
  }

  private positionEvents(events: CalendarEvent[]): PositionedEvent[] {
    if (events.length === 0) return [];

    const sorted = [...events].sort((a, b) => a.start.getTime() - b.start.getTime());
    const positioned: PositionedEvent[] = [];

    const groups: CalendarEvent[][] = [];
    let currentGroup: CalendarEvent[] = [];
    let groupEnd: Date | null = null;

    for (const evt of sorted) {
      if (groupEnd && evt.start >= groupEnd) {
        if (currentGroup.length > 0) groups.push(currentGroup);
        currentGroup = [];
        groupEnd = null;
      }
      currentGroup.push(evt);
      if (!groupEnd || evt.end > groupEnd) {
        groupEnd = evt.end;
      }
    }
    if (currentGroup.length > 0) groups.push(currentGroup);

    for (const group of groups) {
      const numColumns = group.length;
      group.forEach((evt, colIndex) => {
        const startMin = this.getMinutes(evt, true);
        const endMin = this.getMinutes(evt, false);
        const dur = Math.max(endMin - startMin, 15);
        const top = (startMin / 60) * this.hourHeight;
        const height = (dur / 60) * this.hourHeight;

        positioned.push({
          event: evt,
          top,
          height: Math.max(height, 24),
          left: (colIndex / numColumns) * 100,
          width: (1 / numColumns) * 100,
          color: this.getEventColor(evt),
        });
      });
    }

    return positioned;
  }

  private getMinutes(event: CalendarEvent, isStart: boolean): number {
    const d = isStart ? event.start : event.end;
    if (isSameDay(d, this.currentDate)) {
      return d.getHours() * 60 + d.getMinutes();
    }
    return isStart ? 0 : 24 * 60;
  }

  getEventColor(event: CalendarEvent): string {
    if (event.color) return event.color;
    const cal = this.calendars.find(c => c.id === event.calendarId);
    return cal?.color || '#1976d2';
  }

  onEventClick(evt: CalendarEvent, e: MouseEvent): void {
    e.stopPropagation();
    this.eventClicked.emit(evt);
  }

  onTimeSlotClick(hour: number, isHalf: boolean): void {
    this.timeSlotClicked.emit({
      date: this.currentDate,
      hour,
      minute: isHalf ? 30 : 0,
    });
  }

  formatHour(hour: number): string {
    return `${hour}:00`;
  }

  getGuestInitials(evt: CalendarEvent): string[] {
    return evt.guests.slice(0, 3).map(g => {
      const name = g.displayName || g.email;
      return name.charAt(0);
    });
  }

  trackByHour(index: number, hour: number): number {
    return hour;
  }

  trackByEvent(index: number, pe: PositionedEvent): string {
    return pe.event.id;
  }
}
