import {
  Component,
  ChangeDetectionStrategy,
  OnInit,
  OnDestroy,
  HostListener,
  ChangeDetectorRef,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { ActivatedRoute } from '@angular/router';
import { Title } from '@angular/platform-browser';
import { MatDialog, MatDialogModule } from '@angular/material/dialog';
import { NotificationService } from '../../../../shared/services/notification.service';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';
import { Subject, takeUntil, combineLatest } from 'rxjs';

import { Calendar, CalendarView } from '../../models/calendar.model';
import { CalendarEvent, EventResponseStatus } from '../../models/event.model';
import { CalendarService } from '../../services/calendar.service';
import { buildEventsDateMap } from '../../mock/mock-calendar-data';

import { CalendarSidebarComponent } from '../../components/calendar-sidebar/calendar-sidebar.component';
import { CalendarHeaderComponent } from '../../components/calendar-header/calendar-header.component';
import { CalendarMonthViewComponent } from '../../components/calendar-month-view/calendar-month-view.component';
import { CalendarWeekViewComponent } from '../../components/calendar-week-view/calendar-week-view.component';
import { CalendarDayViewComponent } from '../../components/calendar-day-view/calendar-day-view.component';
import { EventDetailComponent } from '../../components/event-detail/event-detail.component';
import { EventEditorComponent, EventEditorData } from '../../components/event-editor/event-editor.component';

import { format } from 'date-fns';

@Component({
  selector: 'app-calendar-page',
  standalone: true,
  imports: [
    CommonModule,
    MatDialogModule,
    MatButtonModule,
    MatIconModule,
    CalendarSidebarComponent,
    CalendarHeaderComponent,
    CalendarMonthViewComponent,
    CalendarWeekViewComponent,
    CalendarDayViewComponent,
    EventDetailComponent,
  ],
  templateUrl: './calendar-page.component.html',
  styleUrls: ['./calendar-page.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CalendarPageComponent implements OnInit, OnDestroy {
  currentDate = new Date();
  currentView: CalendarView = 'week7';
  calendars: Calendar[] = [];
  events: CalendarEvent[] = [];
  allEvents: CalendarEvent[] = [];
  visibleCalendarIds: string[] = [];
  /** カレンダー内の検索クエリ (タイトル/詳細/場所) */
  eventSearchQuery = '';
  /** Google Calendar 風ドロップダウン用の検索結果 (最大 10 件) */
  searchResultsForHeader: any[] = [];

  selectedEvent: CalendarEvent | null = null;
  selectedEventCalendar: Calendar | undefined;
  showEventDetail = false;
  detailPosition = { top: 0, left: 0 };

  eventsDateMap = new Map<string, boolean>();

  sidebarCollapsed = false;
  isMobile = false;

  private destroy$ = new Subject<void>();

  constructor(
    private calendarService: CalendarService,
    private dialog: MatDialog,
    private notification: NotificationService,
    private cdr: ChangeDetectorRef,
    private titleService: Title,
    private route: ActivatedRoute,
  ) {}

  ngOnInit(): void {
    this.titleService.setTitle('カレンダー | 日程調整ツール"スケコン"');
    this.checkResponsive();

    /* ユーザー指示 2026-04-23: グローバル検索からの ?q= を引き継ぐ */
    this.route.queryParams.pipe(takeUntil(this.destroy$)).subscribe(params => {
      if (params['q']) {
        this.eventSearchQuery = params['q'];
        this.onEventSearch(params['q']);
      }
    });

    combineLatest([
      this.calendarService.listCalendars(),
      this.calendarService.events$,
    ])
      .pipe(takeUntil(this.destroy$))
      .subscribe(([calendars, events]) => {
        this.calendars = calendars;
        this.allEvents = events;
        this.events = this.applyEventSearch(events);
        this.visibleCalendarIds = calendars
          .filter(c => c.visible)
          .map(c => c.id);
        this.eventsDateMap = buildEventsDateMap(
          this.events.filter(e => this.visibleCalendarIds.includes(e.calendarId))
        );
        this.cdr.markForCheck();
      });
  }

  /** 検索クエリ適用 (タイトル / 説明 / 場所をターゲット) */
  private applyEventSearch(list: CalendarEvent[]): CalendarEvent[] {
    const q = this.eventSearchQuery.trim().toLowerCase();
    if (!q) return list;
    return list.filter(e =>
      (e.title || '').toLowerCase().includes(q) ||
      ((e as any).description || '').toLowerCase().includes(q) ||
      ((e as any).location || '').toLowerCase().includes(q)
    );
  }

  /** ヘッダーの検索バーから呼ばれる */
  onEventSearch(q: string): void {
    this.eventSearchQuery = q;
    this.events = this.applyEventSearch(this.allEvents);
    this.eventsDateMap = buildEventsDateMap(
      this.events.filter(e => this.visibleCalendarIds.includes(e.calendarId))
    );
    // Google Calendar 風ドロップダウン用の結果を用意 (可視カレンダーのみ、日付順)
    if (q) {
      const visible = new Set(this.visibleCalendarIds);
      this.searchResultsForHeader = this.applyEventSearch(this.allEvents)
        .filter(e => visible.has(e.calendarId))
        .slice()
        .sort((a, b) => (a.start?.getTime?.() || 0) - (b.start?.getTime?.() || 0))
        .slice(0, 20)
        .map(e => {
          const cal = this.calendars.find(c => c.id === e.calendarId);
          const d = e.start;
          const dateLabel = d
            ? `${d.getMonth() + 1}/${d.getDate()} ${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`
            : '';
          return { ...e, _color: cal?.color || '#1a73e8', _dateLabel: dateLabel };
        });
    } else {
      this.searchResultsForHeader = [];
    }
    this.cdr.markForCheck();
  }

  /** ドロップダウンから選択されたイベントを開く */
  onSearchEventSelected(event: any): void {
    if (event?.start) {
      this.currentDate = new Date(event.start);
    }
    this.selectedEvent = event;
    this.selectedEventCalendar = this.calendars.find(c => c.id === event.calendarId);
    this.showEventDetail = true;
    this.cdr.markForCheck();
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  @HostListener('window:resize')
  onResize(): void {
    this.checkResponsive();
  }

  @HostListener('window:keydown', ['$event'])
  onKeydown(event: KeyboardEvent): void {
    if (event.target instanceof HTMLInputElement || event.target instanceof HTMLTextAreaElement) {
      return;
    }

    switch (event.key) {
      case 'ArrowLeft':
        this.onDateChanged(this.getAdjacentDate(-1));
        event.preventDefault();
        break;
      case 'ArrowRight':
        this.onDateChanged(this.getAdjacentDate(1));
        event.preventDefault();
        break;
      case 't':
        this.onTodayClicked();
        break;
      case 'd':
        this.onViewChanged('day1');
        break;
      case 'w':
        this.onViewChanged('week7');
        break;
      case 'm':
        this.onViewChanged('month');
        break;
      case 'c':
        this.openEventEditor('create');
        break;
      case 'Escape':
        this.closeEventDetail();
        break;
    }
  }

  private checkResponsive(): void {
    const width = window.innerWidth;
    this.isMobile = width < 768;
    this.sidebarCollapsed = width < 1024;

    // Keep isMobile for layout purposes but don't force the view
    this.cdr.markForCheck();
  }

  private getAdjacentDate(direction: number): Date {
    const d = new Date(this.currentDate);
    switch (this.currentView) {
      case 'month':
        d.setMonth(d.getMonth() + direction);
        break;
      case 'week7':
        d.setDate(d.getDate() + 7 * direction);
        break;
      case 'week5':
        d.setDate(d.getDate() + 5 * direction);
        break;
      case 'day3':
        d.setDate(d.getDate() + 3 * direction);
        break;
      case 'day1':
        d.setDate(d.getDate() + direction);
        break;
    }
    return d;
  }

  // === Header events ===
  onDateChanged(date: Date): void {
    this.currentDate = date;
    this.cdr.markForCheck();
  }

  onViewChanged(view: CalendarView): void {
    this.currentView = view;
    this.cdr.markForCheck();
  }

  onTodayClicked(): void {
    this.currentDate = new Date();
    this.cdr.markForCheck();
  }

  // === Sidebar events ===
  onDateSelected(date: Date): void {
    this.currentDate = date;
    this.cdr.markForCheck();
  }

  onCreateEventClicked(): void {
    this.openEventEditor('create');
  }

  onCalendarVisibilityToggled(calendarId: string): void {
    this.calendarService.toggleCalendarVisibility(calendarId);
  }

  /** 右クリック: このカレンダーだけ表示 (他は全部非表示) — もう一度押すと全表示に戻る */
  onCalendarSoloToggled(calendarId: string): void {
    const visibleIds = this.calendars.filter(c => c.visible).map(c => c.id);
    const isAlreadySolo = visibleIds.length === 1 && visibleIds[0] === calendarId;
    this.calendars.forEach(c => {
      const shouldBeVisible = isAlreadySolo ? true : c.id === calendarId;
      if (c.visible !== shouldBeVisible) {
        this.calendarService.toggleCalendarVisibility(c.id);
      }
    });
  }

  onMonthChanged(date: Date): void {
    // Optional: sync the main view's month with the mini calendar
  }

  // === View events ===
  onEventClicked(event: CalendarEvent): void {
    this.selectedEvent = event;
    this.selectedEventCalendar = this.calendars.find(
      c => c.id === event.calendarId
    );
    this.showEventDetail = true;
    this.cdr.markForCheck();
  }

  onDateClicked(date: Date): void {
    this.currentDate = date;
    // If in month view, switch to day view
    if (this.currentView === 'month') {
      this.currentView = 'day1';
    }
    this.cdr.markForCheck();
  }

  onTimeSlotClicked(data: { date: Date; hour: number; minute: number }): void {
    const hh = String(data.hour).padStart(2, '0');
    const mm = String(data.minute).padStart(2, '0');
    const startTime = `${hh}:${mm}`;
    const endHour = data.minute >= 30 ? data.hour + 1 : data.hour;
    const endMin = data.minute >= 30 ? data.minute - 30 : data.minute + 30;
    const endTime = `${String(endHour).padStart(2, '0')}:${String(endMin).padStart(2, '0')}`;

    this.openEventEditor('create', undefined, data.date, startTime, endTime);
  }

  onMoreEventsClicked(data: { date: Date; events: CalendarEvent[] }): void {
    this.currentDate = data.date;
    this.currentView = 'day1';
    this.cdr.markForCheck();
  }

  onTimeSlotDragged(data: { date: Date; startTime: string; endTime: string }): void {
    this.openEventEditor('create', undefined, data.date, data.startTime, data.endTime);
  }

  // === Event detail events ===
  closeEventDetail(): void {
    this.showEventDetail = false;
    this.selectedEvent = null;
    this.cdr.markForCheck();
  }

  onEventDetailEdit(event: CalendarEvent): void {
    this.closeEventDetail();
    this.openEventEditor('edit', event);
  }

  onEventDetailDelete(event: CalendarEvent): void {
    this.closeEventDetail();
    this.calendarService.deleteEvent(event.id).subscribe(() => {
      this.notification.warn('予定を削除しました');
    });
  }

  onEventDetailResponse(data: { event: CalendarEvent; response: EventResponseStatus }): void {
    this.calendarService.respondToEvent(data.event.id, data.response).subscribe();
    this.notification.success('出欠を更新しました');
  }

  /** 予定詳細からメールで招待 (ユーザー指示 2026-04-21) */
  onEventDetailInvite(data: { event: CalendarEvent; emails: string[] }): void {
    this.calendarService.inviteGuests(data.event.id, data.emails).subscribe(updated => {
      if (this.selectedEvent && this.selectedEvent.id === updated.id) {
        this.selectedEvent = updated;
        this.cdr.markForCheck();
      }
      this.notification.success(
        `${data.emails.length}名を招待しました`
      );
    });
  }

  /**
   * 予定詳細から「複製」: Google カレンダー と同じ挙動 (ユーザー指示 2026-04-21)
   * → 予定エディタが開き、元予定の値が全てプリフィルされた "新規作成" 状態で立ち上がる。
   *   ユーザーが中身を確認・編集して「保存」を押すと新しい予定として作成される。
   */
  onEventDetailDuplicate(event: CalendarEvent): void {
    this.closeEventDetail();

    // 繰り返しインスタンス (-rec-) の場合はその発生日時をそのまま複製元に使う
    const sourceEvent: CalendarEvent = {
      ...event,
      // id を外して、create モードで新規扱いになるようにする (id 自体は editor で無視される)
      id: '',
      guests: event.guests ? event.guests.map(g => ({ ...g })) : [],
      reminders: event.reminders ? event.reminders.map(r => ({ ...r })) : [],
      start: new Date(event.start),
      end: new Date(event.end),
    } as CalendarEvent;

    const data: EventEditorData = {
      mode: 'create',
      event: sourceEvent,
      calendars: this.calendars.filter(
        c => c.id !== 'cal-holidays' && c.id !== 'cal-tanaka'
      ),
      initialDate: this.currentDate,
    };

    const dialogRef = this.dialog.open(EventEditorComponent, {
      data,
      panelClass: 'event-editor-dialog',
      maxHeight: '90vh',
      disableClose: false,
    });

    dialogRef.afterClosed().subscribe(result => {
      if (!result) return;
      if (result.action === 'save') {
        this.calendarService.createEvent(result.event).subscribe(() => {
          this.notification.success('予定を複製しました');
        });
      }
    });
  }

  /** 予定をドラッグで移動 (ユーザー指示 2026-04-21) */
  onEventMoved(data: { event: CalendarEvent; newStart: Date; newEnd: Date }): void {
    // 繰り返し展開されたインスタンスは元IDを使う
    const baseId = data.event.id.includes('-rec-')
      ? data.event.id.split('-rec-')[0]
      : data.event.id;
    this.calendarService
      .updateEvent(baseId, { start: data.newStart, end: data.newEnd })
      .subscribe(() => {
        this.notification.success('予定を移動しました');
      });
  }

  // === Event editor ===
  openEventEditor(
    mode: 'create' | 'edit',
    event?: CalendarEvent,
    initialDate?: Date,
    initialStartTime?: string,
    initialEndTime?: string
  ): void {
    const data: EventEditorData = {
      mode,
      event,
      calendars: this.calendars.filter(
        c => c.id !== 'cal-holidays' && c.id !== 'cal-tanaka'
      ),
      initialDate: initialDate || this.currentDate,
      initialStartTime,
      initialEndTime,
    };

    const dialogRef = this.dialog.open(EventEditorComponent, {
      data,
      panelClass: 'event-editor-dialog',
      maxHeight: '90vh',
      disableClose: false,
    });

    dialogRef.afterClosed().subscribe(result => {
      if (!result) return;

      switch (result.action) {
        case 'save':
          if (mode === 'edit' && result.event.id) {
            this.calendarService
              .updateEvent(result.event.id, result.event)
              .subscribe(() => {
                this.notification.success('予定を更新しました');
              });
          } else {
            this.calendarService.createEvent(result.event).subscribe(() => {
              this.notification.success('予定を作成しました');
            });
          }
          break;

        case 'delete':
          if (result.event?.id) {
            this.calendarService.deleteEvent(result.event.id).subscribe(() => {
              this.notification.warn('予定を削除しました');
            });
          }
          break;
      }
    });
  }

  // === Mobile FAB ===
  onMobileFab(): void {
    this.openEventEditor('create');
  }

  // === Overlay click ===
  onOverlayClick(): void {
    this.closeEventDetail();
  }

  get weekViewType(): 'week7' | 'week5' | 'day3' {
    if (this.currentView === 'week7') return 'week7';
    if (this.currentView === 'week5') return 'week5';
    return 'day3';
  }
}
