import {
  Component,
  ChangeDetectionStrategy,
  Input,
  Output,
  EventEmitter,
  OnChanges,
  OnInit,
  OnDestroy,
  SimpleChanges,
  ElementRef,
  ViewChild,
  AfterViewInit,
  NgZone,
  ChangeDetectorRef,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { CalendarEvent } from '../../models/event.model';
import { Calendar, CalendarView } from '../../models/calendar.model';
import {
  startOfWeek,
  addDays,
  isSameDay,
  format,
  differenceInMinutes,
  startOfDay,
  endOfDay,
  areIntervalsOverlapping,
  isToday,
  setHours,
  setMinutes,
} from 'date-fns';
import { ja } from 'date-fns/locale';

interface DayColumn {
  date: Date;
  label: string;
  dayOfWeek: string;
  isToday: boolean;
  allDayEvents: CalendarEvent[];
  timedEvents: PositionedEvent[];
}

interface PositionedEvent {
  event: CalendarEvent;
  top: number;
  height: number;
  left: number;
  width: number;
  color: string;
}

interface DragState {
  active: boolean;
  columnIndex: number;
  startMinutes: number;
  currentMinutes: number;
}

/** 既存予定ドラッグ (ユーザー指示 2026-04-21): 予定を掴んで別時間/別日へ移動 */
interface MoveState {
  active: boolean;
  event: CalendarEvent | null;
  originalStart: Date;
  originalEnd: Date;
  originColumnIndex: number;
  currentColumnIndex: number;
  startMinutes: number;
  currentMinutes: number;
  durationMinutes: number;
  grabOffsetMinutes: number;
}

@Component({
  selector: 'app-calendar-week-view',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './calendar-week-view.component.html',
  styleUrls: ['./calendar-week-view.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CalendarWeekViewComponent implements OnChanges, OnInit, OnDestroy, AfterViewInit {
  @Input({ required: true }) currentDate!: Date;
  @Input() events: CalendarEvent[] = [];
  @Input() visibleCalendarIds: string[] = [];
  @Input() calendars: Calendar[] = [];
  @Input() viewType: 'week7' | 'week5' | 'day3' = 'week7';

  @Output() eventClicked = new EventEmitter<CalendarEvent>();
  @Output() timeSlotClicked = new EventEmitter<{ date: Date; hour: number; minute: number }>();
  @Output() eventMoved = new EventEmitter<{ event: CalendarEvent; newStart: Date; newEnd: Date }>();
  @Output() eventResized = new EventEmitter<{ event: CalendarEvent; newEnd: Date }>();
  @Output() timeSlotDragged = new EventEmitter<{ date: Date; startTime: string; endTime: string }>();

  @ViewChild('timeGrid') timeGridRef!: ElementRef<HTMLDivElement>;

  columns: DayColumn[] = [];
  hours: number[] = [];
  currentTimeTop = 0;
  currentTimeVisible = false;
  private timerInterval: ReturnType<typeof setInterval> | null = null;
  readonly hourHeight = 48;
  private readonly startHour = 0;
  private readonly endHour = 24;

  today = new Date();
  hasAllDayEvents = false;

  // Drag-to-create state
  dragState: DragState = {
    active: false,
    columnIndex: -1,
    startMinutes: 0,
    currentMinutes: 0,
  };

  // Drag-to-move existing event state (ユーザー指示 2026-04-21)
  moveState: MoveState = {
    active: false,
    event: null,
    originalStart: new Date(),
    originalEnd: new Date(),
    originColumnIndex: -1,
    currentColumnIndex: -1,
    startMinutes: 0,
    currentMinutes: 0,
    durationMinutes: 0,
    grabOffsetMinutes: 0,
  };

  private isDragging = false;
  private dragStarted = false;
  private isMoving = false;
  private moveStarted = false;
  private mouseDownY = 0;
  private mouseDownX = 0;
  private readonly DRAG_THRESHOLD = 4; // px before drag starts
  private boundOnMouseMove: ((e: MouseEvent) => void) | null = null;
  private boundOnMouseUp: ((e: MouseEvent) => void) | null = null;
  private boundOnMoveMouseMove: ((e: MouseEvent) => void) | null = null;
  private boundOnMoveMouseUp: ((e: MouseEvent) => void) | null = null;

  constructor(private ngZone: NgZone, private cdr: ChangeDetectorRef) {}

  ngOnInit(): void {
    this.hours = [];
    for (let h = this.startHour; h < this.endHour; h++) {
      this.hours.push(h);
    }
    this.updateCurrentTime();
    this.timerInterval = setInterval(() => this.updateCurrentTime(), 60000);
  }

  ngAfterViewInit(): void {
    // Scroll to 7am by default
    setTimeout(() => {
      if (this.timeGridRef) {
        this.timeGridRef.nativeElement.scrollTop = 7 * this.hourHeight;
      }
    }, 0);
  }

  ngOnDestroy(): void {
    if (this.timerInterval) {
      clearInterval(this.timerInterval);
    }
    this.cleanupDragListeners();
    this.cleanupMoveListeners();
  }

  ngOnChanges(changes: SimpleChanges): void {
    this.buildColumns();
    this.hasAllDayEvents = this.columns.some(c => c.allDayEvents.length > 0);
    this.updateCurrentTime();
  }

  private updateCurrentTime(): void {
    const now = new Date();
    const minutesSinceMidnight = now.getHours() * 60 + now.getMinutes();
    this.currentTimeTop = (minutesSinceMidnight / 60) * this.hourHeight;
    this.currentTimeVisible = this.columns.some(c => isSameDay(c.date, now));
  }

  private buildColumns(): void {
    if (!this.currentDate) return;

    const numDays = this.viewType === 'week7' ? 7 : this.viewType === 'week5' ? 5 : 3;
    let startDate: Date;

    if (this.viewType === 'week7' || this.viewType === 'week5') {
      startDate = startOfWeek(this.currentDate, { weekStartsOn: 1 });
    } else {
      startDate = this.currentDate;
    }

    const filteredEvents = this.events.filter(e =>
      this.visibleCalendarIds.includes(e.calendarId)
    );

    this.columns = [];

    for (let i = 0; i < numDays; i++) {
      const date = addDays(startDate, i);
      const dayStart = startOfDay(date);
      const dayEnd = endOfDay(date);

      const dayEvents = filteredEvents.filter(e =>
        areIntervalsOverlapping(
          { start: e.start, end: e.end },
          { start: dayStart, end: dayEnd }
        )
      );

      const allDayEvents = dayEvents.filter(e => e.allDay);
      const timedEvents = dayEvents.filter(e => !e.allDay);

      const positioned = this.positionEvents(timedEvents, date);

      this.columns.push({
        date,
        /* ユーザー指示 (2026-04-21): スマホの日付は "21 (火)" 形式
           (日 の漢字なし) に。label は日付のみに、曜日は dayOfWeek に括弧付き。 */
        label: format(date, 'd', { locale: ja }),
        dayOfWeek: `(${format(date, 'EEEEE', { locale: ja })})`,
        isToday: isToday(date),
        allDayEvents,
        timedEvents: positioned,
      });
    }
  }

  private positionEvents(events: CalendarEvent[], date: Date): PositionedEvent[] {
    if (events.length === 0) return [];

    const sorted = [...events].sort((a, b) => a.start.getTime() - b.start.getTime());
    const positioned: PositionedEvent[] = [];

    // Overlap grouping
    const groups: CalendarEvent[][] = [];
    let currentGroup: CalendarEvent[] = [];
    let groupEnd: Date | null = null;

    for (const evt of sorted) {
      if (groupEnd && evt.start >= groupEnd) {
        if (currentGroup.length > 0) groups.push(currentGroup);
        currentGroup = [];
        groupEnd = null;
      }
      currentGroup.push(evt);
      if (!groupEnd || evt.end > groupEnd) {
        groupEnd = evt.end;
      }
    }
    if (currentGroup.length > 0) groups.push(currentGroup);

    for (const group of groups) {
      const numColumns = group.length;
      group.forEach((evt, colIndex) => {
        const eventStartMinutes = this.getMinutesForEvent(evt, date, true);
        const eventEndMinutes = this.getMinutesForEvent(evt, date, false);
        const durationMinutes = Math.max(eventEndMinutes - eventStartMinutes, 15);

        const top = (eventStartMinutes / 60) * this.hourHeight;
        const height = (durationMinutes / 60) * this.hourHeight;

        positioned.push({
          event: evt,
          top,
          height: Math.max(height, 18),
          left: (colIndex / numColumns) * 100,
          width: (1 / numColumns) * 100,
          color: this.getEventColor(evt),
        });
      });
    }

    return positioned;
  }

  private getMinutesForEvent(event: CalendarEvent, date: Date, isStart: boolean): number {
    const d = isStart ? event.start : event.end;
    if (isSameDay(d, date)) {
      return d.getHours() * 60 + d.getMinutes();
    }
    return isStart ? 0 : 24 * 60;
  }

  getEventColor(event: CalendarEvent): string {
    if (event.color) return event.color;
    const cal = this.calendars.find(c => c.id === event.calendarId);
    return cal?.color || '#1976d2';
  }

  onEventClick(evt: CalendarEvent, e: MouseEvent): void {
    e.stopPropagation();
    // 直前にドラッグで移動していた場合はクリック扱いしない
    if (this.moveStarted) {
      this.moveStarted = false;
      return;
    }
    this.eventClicked.emit(evt);
  }

  /**
   * 既存予定 (event-block) 上での mousedown: ドラッグで移動するか、
   * 閾値を超えなかったらクリック扱い。
   * (ユーザー指示 2026-04-21)
   */
  onEventMouseDown(pe: PositionedEvent, columnIndex: number, e: MouseEvent): void {
    if (e.button !== 0) return;
    // 繰り返しイベントの展開分は移動不可 (IDが `-rec-` 付き)
    if (pe.event.id.includes('-rec-')) return;

    e.stopPropagation();
    this.isMoving = true;
    this.moveStarted = false;
    this.mouseDownY = e.clientY;
    this.mouseDownX = e.clientX;

    const col = this.columns[columnIndex];
    if (!col) return;

    const durationMin = Math.max(
      differenceInMinutes(pe.event.end, pe.event.start),
      15
    );
    const clickMinutes = this.snapTo15Min(this.getMinutesFromMouseEvent(e));
    const eventStartMin =
      pe.event.start.getHours() * 60 + pe.event.start.getMinutes();
    const grabOffset = Math.max(0, clickMinutes - eventStartMin);

    this.moveState = {
      active: false,
      event: pe.event,
      originalStart: new Date(pe.event.start),
      originalEnd: new Date(pe.event.end),
      originColumnIndex: columnIndex,
      currentColumnIndex: columnIndex,
      startMinutes: eventStartMin,
      currentMinutes: eventStartMin,
      durationMinutes: durationMin,
      grabOffsetMinutes: grabOffset,
    };

    this.ngZone.runOutsideAngular(() => {
      this.boundOnMoveMouseMove = this.onMoveMouseMove.bind(this);
      this.boundOnMoveMouseUp = this.onMoveMouseUp.bind(this);
      document.addEventListener('mousemove', this.boundOnMoveMouseMove);
      document.addEventListener('mouseup', this.boundOnMoveMouseUp);
    });

    e.preventDefault();
  }

  private onMoveMouseMove(e: MouseEvent): void {
    if (!this.isMoving || !this.moveState.event) return;

    if (!this.moveStarted) {
      const dy = Math.abs(e.clientY - this.mouseDownY);
      const dx = Math.abs(e.clientX - this.mouseDownX);
      if (dy < this.DRAG_THRESHOLD && dx < this.DRAG_THRESHOLD) return;
      this.moveStarted = true;
      this.moveState.active = true;
    }

    const minutes = this.snapTo15Min(this.getMinutesFromMouseEvent(e));
    const newStart = minutes - this.moveState.grabOffsetMinutes;
    this.moveState.currentMinutes = Math.max(
      0,
      Math.min(newStart, 1440 - this.moveState.durationMinutes)
    );

    // どのカラム (日) にいるかを判定
    const targetColIdx = this.getColumnIndexFromMouseEvent(e);
    if (targetColIdx >= 0) {
      this.moveState.currentColumnIndex = targetColIdx;
    }

    this.ngZone.run(() => this.cdr.markForCheck());
  }

  private onMoveMouseUp(e: MouseEvent): void {
    this.cleanupMoveListeners();
    if (!this.isMoving) return;
    this.isMoving = false;

    if (!this.moveStarted || !this.moveState.active || !this.moveState.event) {
      this.resetMove();
      return;
    }

    const targetCol = this.columns[this.moveState.currentColumnIndex];
    const originalCol = this.columns[this.moveState.originColumnIndex];
    const sameStart =
      targetCol &&
      originalCol &&
      isSameDay(targetCol.date, originalCol.date) &&
      this.moveState.currentMinutes === this.moveState.startMinutes;

    if (!targetCol || sameStart) {
      this.resetMove();
      return;
    }

    const newStart = new Date(targetCol.date);
    newStart.setHours(
      Math.floor(this.moveState.currentMinutes / 60),
      this.moveState.currentMinutes % 60,
      0,
      0
    );
    const newEnd = new Date(
      newStart.getTime() + this.moveState.durationMinutes * 60 * 1000
    );

    const movedEvent = this.moveState.event;
    this.ngZone.run(() => {
      this.eventMoved.emit({ event: movedEvent, newStart, newEnd });
      this.resetMove();
    });
  }

  private cleanupMoveListeners(): void {
    if (this.boundOnMoveMouseMove) {
      document.removeEventListener('mousemove', this.boundOnMoveMouseMove);
      this.boundOnMoveMouseMove = null;
    }
    if (this.boundOnMoveMouseUp) {
      document.removeEventListener('mouseup', this.boundOnMoveMouseUp);
      this.boundOnMoveMouseUp = null;
    }
  }

  private resetMove(): void {
    this.moveState = {
      active: false,
      event: null,
      originalStart: new Date(),
      originalEnd: new Date(),
      originColumnIndex: -1,
      currentColumnIndex: -1,
      startMinutes: 0,
      currentMinutes: 0,
      durationMinutes: 0,
      grabOffsetMinutes: 0,
    };
    this.isMoving = false;
    // moveStarted は直後の click 判定に使うので残す; onEventClick が消費
    this.cdr.markForCheck();
  }

  /** マウス位置からカラム (日付列) のインデックスを求める */
  private getColumnIndexFromMouseEvent(e: MouseEvent): number {
    if (!this.timeGridRef) return -1;
    const gridEl = this.timeGridRef.nativeElement;
    const rect = gridEl.getBoundingClientRect();
    // ガター幅 56px を除外 (スタイル $gutter-width と一致)
    const gutter = 56;
    const xInGrid = e.clientX - rect.left - gutter;
    const contentWidth = rect.width - gutter;
    if (contentWidth <= 0 || xInGrid < 0) return -1;
    const ratio = xInGrid / contentWidth;
    const idx = Math.floor(ratio * this.columns.length);
    return Math.max(0, Math.min(this.columns.length - 1, idx));
  }

  /** 移動中のプレビュー表示用 */
  get movePreviewTop(): number {
    return (this.moveState.currentMinutes / 60) * this.hourHeight;
  }

  get movePreviewHeight(): number {
    return (this.moveState.durationMinutes / 60) * this.hourHeight;
  }

  get movePreviewTimeLabel(): string {
    const startMin = this.moveState.currentMinutes;
    const endMin = startMin + this.moveState.durationMinutes;
    return `${this.minutesToTimeString(startMin)} - ${this.minutesToTimeString(endMin)}`;
  }

  isMovingSourceBlock(pe: PositionedEvent): boolean {
    return (
      this.moveState.active &&
      !!this.moveState.event &&
      pe.event.id === this.moveState.event.id
    );
  }

  onTimeSlotClick(column: DayColumn, hour: number, isHalf: boolean, e: MouseEvent): void {
    // Only fire if we are not dragging
    if (this.dragStarted) return;
    this.timeSlotClicked.emit({
      date: column.date,
      hour,
      minute: isHalf ? 30 : 0,
    });
  }

  formatHour(hour: number): string {
    return `${hour}:00`;
  }

  currentTimeColumnIndex(): number {
    const now = new Date();
    return this.columns.findIndex(c => isSameDay(c.date, now));
  }

  trackByColumn(index: number, col: DayColumn): string {
    return col.date.toISOString();
  }

  trackByEvent(index: number, pe: PositionedEvent): string {
    return pe.event.id;
  }

  trackByHour(index: number, hour: number): number {
    return hour;
  }

  // =============================================
  // Drag-to-create event handling
  // =============================================

  onGridMouseDown(event: MouseEvent, columnIndex: number): void {
    // Ignore right-click
    if (event.button !== 0) return;

    // Don't start drag if clicking on an event
    const target = event.target as HTMLElement;
    if (target.closest('.week-view__event-block')) return;

    this.isDragging = true;
    this.dragStarted = false;
    this.mouseDownY = event.clientY;

    const minutes = this.getMinutesFromMouseEvent(event);
    const snappedMinutes = this.snapTo15Min(minutes);

    this.dragState = {
      active: false,
      columnIndex,
      startMinutes: snappedMinutes,
      currentMinutes: snappedMinutes,
    };

    // Attach global mousemove/mouseup outside Angular zone for performance
    this.ngZone.runOutsideAngular(() => {
      this.boundOnMouseMove = this.onDocumentMouseMove.bind(this);
      this.boundOnMouseUp = this.onDocumentMouseUp.bind(this);
      document.addEventListener('mousemove', this.boundOnMouseMove);
      document.addEventListener('mouseup', this.boundOnMouseUp);
    });

    event.preventDefault();
  }

  private onDocumentMouseMove(event: MouseEvent): void {
    if (!this.isDragging) return;

    // Check if we've moved enough to consider it a drag
    if (!this.dragStarted) {
      const dy = Math.abs(event.clientY - this.mouseDownY);
      if (dy < this.DRAG_THRESHOLD) return;
      this.dragStarted = true;
      this.dragState.active = true;
    }

    const minutes = this.getMinutesFromMouseEvent(event);
    const snappedMinutes = this.snapTo15Min(minutes);
    this.dragState.currentMinutes = snappedMinutes;

    this.ngZone.run(() => {
      this.cdr.markForCheck();
    });
  }

  private onDocumentMouseUp(event: MouseEvent): void {
    this.cleanupDragListeners();

    if (!this.isDragging) return;
    this.isDragging = false;

    if (!this.dragStarted || !this.dragState.active) {
      this.dragState.active = false;
      this.dragStarted = false;
      this.ngZone.run(() => {
        this.cdr.markForCheck();
      });
      return;
    }

    // Calculate final time range
    const col = this.columns[this.dragState.columnIndex];
    if (!col) {
      this.resetDrag();
      return;
    }

    let startMin = Math.min(this.dragState.startMinutes, this.dragState.currentMinutes);
    let endMin = Math.max(this.dragState.startMinutes, this.dragState.currentMinutes);

    // Ensure minimum 15-minute event
    if (endMin - startMin < 15) {
      endMin = startMin + 15;
    }

    // Clamp to 0-1440
    startMin = Math.max(0, Math.min(startMin, 1440 - 15));
    endMin = Math.max(15, Math.min(endMin, 1440));

    const startTime = this.minutesToTimeString(startMin);
    const endTime = this.minutesToTimeString(endMin);

    this.ngZone.run(() => {
      this.timeSlotDragged.emit({
        date: col.date,
        startTime,
        endTime,
      });
      this.resetDrag();
    });
  }

  private cleanupDragListeners(): void {
    if (this.boundOnMouseMove) {
      document.removeEventListener('mousemove', this.boundOnMouseMove);
      this.boundOnMouseMove = null;
    }
    if (this.boundOnMouseUp) {
      document.removeEventListener('mouseup', this.boundOnMouseUp);
      this.boundOnMouseUp = null;
    }
  }

  private resetDrag(): void {
    this.dragState = {
      active: false,
      columnIndex: -1,
      startMinutes: 0,
      currentMinutes: 0,
    };
    this.isDragging = false;
    this.dragStarted = false;
    this.cdr.markForCheck();
  }

  private getMinutesFromMouseEvent(event: MouseEvent): number {
    if (!this.timeGridRef) return 0;
    const gridEl = this.timeGridRef.nativeElement;
    const rect = gridEl.getBoundingClientRect();
    const scrollTop = gridEl.scrollTop;
    const yInGrid = event.clientY - rect.top + scrollTop;
    const minutes = (yInGrid / this.hourHeight) * 60;
    return Math.max(0, Math.min(minutes, 1440));
  }

  private snapTo15Min(minutes: number): number {
    return Math.round(minutes / 15) * 15;
  }

  private minutesToTimeString(minutes: number): string {
    const h = Math.floor(minutes / 60);
    const m = minutes % 60;
    return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
  }

  // Computed properties for the drag preview
  get dragPreviewTop(): number {
    const startMin = Math.min(this.dragState.startMinutes, this.dragState.currentMinutes);
    return (startMin / 60) * this.hourHeight;
  }

  get dragPreviewHeight(): number {
    const startMin = Math.min(this.dragState.startMinutes, this.dragState.currentMinutes);
    const endMin = Math.max(this.dragState.startMinutes, this.dragState.currentMinutes);
    const diff = Math.max(endMin - startMin, 15);
    return (diff / 60) * this.hourHeight;
  }

  get dragPreviewTimeLabel(): string {
    const startMin = Math.min(this.dragState.startMinutes, this.dragState.currentMinutes);
    let endMin = Math.max(this.dragState.startMinutes, this.dragState.currentMinutes);
    if (endMin - startMin < 15) {
      endMin = startMin + 15;
    }
    return `${this.minutesToTimeString(startMin)} - ${this.minutesToTimeString(endMin)}`;
  }
}
