import {
  Component,
  ChangeDetectionStrategy,
  Input,
  Output,
  EventEmitter,
  OnChanges,
  SimpleChanges,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { CalendarEvent } from '../../models/event.model';
import { Calendar } from '../../models/calendar.model';
import { EventChipComponent } from '../event-chip/event-chip.component';
import {
  startOfMonth,
  endOfMonth,
  startOfWeek,
  endOfWeek,
  eachDayOfInterval,
  isSameDay,
  isSameMonth,
  format,
  isWeekend,
  areIntervalsOverlapping,
  startOfDay,
  endOfDay,
} from 'date-fns';

interface MonthCell {
  date: Date;
  dayNumber: number;
  isCurrentMonth: boolean;
  isToday: boolean;
  isWeekend: boolean;
  events: CalendarEvent[];
  hasMore: boolean;
  moreCount: number;
}

@Component({
  selector: 'app-calendar-month-view',
  standalone: true,
  imports: [CommonModule, EventChipComponent],
  templateUrl: './calendar-month-view.component.html',
  styleUrls: ['./calendar-month-view.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CalendarMonthViewComponent implements OnChanges {
  @Input({ required: true }) currentDate!: Date;
  @Input() events: CalendarEvent[] = [];
  @Input() visibleCalendarIds: string[] = [];
  @Input() calendars: Calendar[] = [];

  @Output() dateClicked = new EventEmitter<Date>();
  @Output() eventClicked = new EventEmitter<CalendarEvent>();
  @Output() eventMoved = new EventEmitter<{ event: CalendarEvent; newDate: Date }>();
  @Output() moreEventsClicked = new EventEmitter<{ date: Date; events: CalendarEvent[] }>();

  weeks: MonthCell[][] = [];
  weekDayLabels = ['月', '火', '水', '木', '金', '土', '日'];
  today = new Date();
  maxEventsPerCell = 3;

  ngOnChanges(changes: SimpleChanges): void {
    this.buildGrid();
  }

  private buildGrid(): void {
    if (!this.currentDate) return;

    const monthStart = startOfMonth(this.currentDate);
    const monthEnd = endOfMonth(this.currentDate);
    const calendarStart = startOfWeek(monthStart, { weekStartsOn: 1 });
    const calendarEnd = endOfWeek(monthEnd, { weekStartsOn: 1 });
    const allDays = eachDayOfInterval({ start: calendarStart, end: calendarEnd });

    const filteredEvents = this.events.filter(e =>
      this.visibleCalendarIds.includes(e.calendarId)
    );

    this.weeks = [];
    let currentWeek: MonthCell[] = [];

    for (const day of allDays) {
      const dayStart = startOfDay(day);
      const dayEnd = endOfDay(day);

      const dayEvents = filteredEvents.filter(e =>
        areIntervalsOverlapping(
          { start: e.start, end: e.end },
          { start: dayStart, end: dayEnd }
        )
      );

      // Sort: all-day first, then by start time
      dayEvents.sort((a, b) => {
        if (a.allDay && !b.allDay) return -1;
        if (!a.allDay && b.allDay) return 1;
        return a.start.getTime() - b.start.getTime();
      });

      const cell: MonthCell = {
        date: day,
        dayNumber: day.getDate(),
        isCurrentMonth: isSameMonth(day, this.currentDate),
        isToday: isSameDay(day, this.today),
        isWeekend: isWeekend(day),
        events: dayEvents.slice(0, this.maxEventsPerCell),
        hasMore: dayEvents.length > this.maxEventsPerCell,
        moreCount: dayEvents.length - this.maxEventsPerCell,
      };

      currentWeek.push(cell);

      if (currentWeek.length === 7) {
        this.weeks.push(currentWeek);
        currentWeek = [];
      }
    }

    if (currentWeek.length > 0) {
      this.weeks.push(currentWeek);
    }
  }

  getEventColor(event: CalendarEvent): string {
    if (event.color) return event.color;
    const cal = this.calendars.find(c => c.id === event.calendarId);
    return cal?.color || '#1976d2';
  }

  onCellClick(cell: MonthCell, event: MouseEvent): void {
    this.dateClicked.emit(cell.date);
  }

  onEventClick(evt: CalendarEvent): void {
    this.eventClicked.emit(evt);
  }

  onMoreClick(cell: MonthCell, event: MouseEvent): void {
    event.stopPropagation();
    const dayStart = startOfDay(cell.date);
    const dayEnd = endOfDay(cell.date);
    const allDayEvents = this.events.filter(
      e =>
        this.visibleCalendarIds.includes(e.calendarId) &&
        areIntervalsOverlapping(
          { start: e.start, end: e.end },
          { start: dayStart, end: dayEnd }
        )
    );
    this.moreEventsClicked.emit({ date: cell.date, events: allDayEvents });
  }

  trackByWeek(index: number, week: MonthCell[]): number {
    return index;
  }

  trackByCell(index: number, cell: MonthCell): string {
    return cell.date.toISOString();
  }

  trackByEvent(index: number, event: CalendarEvent): string {
    return event.id;
  }
}
