import { Component, ChangeDetectionStrategy, Input, Output, EventEmitter } from '@angular/core';
import { CommonModule } from '@angular/common';
import { CalendarEvent } from '../../models/event.model';
import { format } from 'date-fns';

@Component({
  selector: 'app-event-chip',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './event-chip.component.html',
  styleUrls: ['./event-chip.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class EventChipComponent {
  @Input({ required: true }) event!: CalendarEvent;
  @Input() color = '#1976d2';
  @Output() eventClicked = new EventEmitter<CalendarEvent>();

  get timeLabel(): string {
    if (this.event.allDay) return '';
    return format(this.event.start, 'H:mm');
  }

  onClick(e: MouseEvent): void {
    e.stopPropagation();
    this.eventClicked.emit(this.event);
  }
}
