import {
  Component,
  ChangeDetectionStrategy,
  Input,
  Output,
  EventEmitter,
  OnChanges,
  SimpleChanges,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatTooltipModule } from '@angular/material/tooltip';
import { Calendar } from '../../models/calendar.model';
import {
  startOfMonth,
  endOfMonth,
  startOfWeek,
  endOfWeek,
  eachDayOfInterval,
  addMonths,
  subMonths,
  isSameDay,
  isSameMonth,
  format,
  getDay,
} from 'date-fns';
import { ja } from 'date-fns/locale';

interface MiniCalendarDay {
  date: Date;
  dayNumber: number;
  isCurrentMonth: boolean;
  isToday: boolean;
  hasEvents: boolean;
}

@Component({
  selector: 'app-calendar-sidebar',
  standalone: true,
  imports: [CommonModule, FormsModule, MatButtonModule, MatIconModule, MatCheckboxModule, MatTooltipModule],
  templateUrl: './calendar-sidebar.component.html',
  styleUrls: ['./calendar-sidebar.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CalendarSidebarComponent implements OnChanges {
  @Input({ required: true }) calendars: Calendar[] = [];
  @Input({ required: true }) currentDate!: Date;
  @Input() eventsMap: Map<string, boolean> = new Map();

  @Output() dateSelected = new EventEmitter<Date>();
  @Output() createEventClicked = new EventEmitter<void>();
  @Output() calendarVisibilityToggled = new EventEmitter<string>();
  @Output() calendarSoloToggled = new EventEmitter<string>();
  @Output() monthChanged = new EventEmitter<Date>();

  miniCalendarMonth!: Date;
  miniCalendarDays: MiniCalendarDay[] = [];
  weekDayLabels = ['月', '火', '水', '木', '金', '土', '日'];
  miniCalendarTitle = '';

  today = new Date();

  /** カレンダー種類の検索語 */
  calendarSearchQuery = '';

  private matchesSearch(cal: Calendar): boolean {
    if (!this.calendarSearchQuery.trim()) return true;
    const q = this.calendarSearchQuery.trim().toLowerCase();
    return (cal.name || '').toLowerCase().includes(q);
  }

  get myCalendars(): Calendar[] {
    return this.calendars.filter(
      c => c.id !== 'cal-tanaka' && c.id !== 'cal-holidays' && this.matchesSearch(c)
    );
  }

  get otherCalendars(): Calendar[] {
    return this.calendars.filter(
      c => (c.id === 'cal-tanaka' || c.id === 'cal-holidays') && this.matchesSearch(c)
    );
  }

  /** 右クリックで「このカレンダーだけ表示」(他のカレンダーは全部非表示) */
  onCalendarContextMenu(event: MouseEvent, calendarId: string): void {
    event.preventDefault();
    event.stopPropagation();
    // 他のカレンダーを一括で非表示、対象カレンダーだけ表示
    this.calendarSoloToggled.emit(calendarId);
  }

  ngOnChanges(changes: SimpleChanges): void {
    /* ユーザー指示 (2026-04-21): PC 左カラムのミニカレンダーが
       メインカレンダーの日付ナビ (前後ボタン / 日/週/月切替) と連動しない
       問題を解消。currentDate が別月に移動したらミニカレンダーの表示月も
       追従するよう、ngOnChanges ごとに月を再計算する。 */
    if (changes['currentDate'] && this.currentDate) {
      const cur = this.miniCalendarMonth;
      const shouldSync = !cur
        || cur.getFullYear() !== this.currentDate.getFullYear()
        || cur.getMonth() !== this.currentDate.getMonth();
      if (shouldSync) {
        this.miniCalendarMonth = new Date(
          this.currentDate.getFullYear(),
          this.currentDate.getMonth(),
          1
        );
      }
    }
    this.buildMiniCalendar();
  }

  buildMiniCalendar(): void {
    if (!this.miniCalendarMonth) return;

    this.miniCalendarTitle = format(this.miniCalendarMonth, 'yyyy年M月', {
      locale: ja,
    });

    const monthStart = startOfMonth(this.miniCalendarMonth);
    const monthEnd = endOfMonth(this.miniCalendarMonth);
    const calendarStart = startOfWeek(monthStart, { weekStartsOn: 1 });
    const calendarEnd = endOfWeek(monthEnd, { weekStartsOn: 1 });

    const days = eachDayOfInterval({ start: calendarStart, end: calendarEnd });

    this.miniCalendarDays = days.map(date => {
      const key = format(date, 'yyyy-MM-dd');
      return {
        date,
        dayNumber: date.getDate(),
        isCurrentMonth: isSameMonth(date, this.miniCalendarMonth),
        isToday: isSameDay(date, this.today),
        hasEvents: this.eventsMap.has(key),
      };
    });
  }

  prevMonth(): void {
    this.miniCalendarMonth = subMonths(this.miniCalendarMonth, 1);
    this.buildMiniCalendar();
    this.monthChanged.emit(this.miniCalendarMonth);
  }

  nextMonth(): void {
    this.miniCalendarMonth = addMonths(this.miniCalendarMonth, 1);
    this.buildMiniCalendar();
    this.monthChanged.emit(this.miniCalendarMonth);
  }

  selectDate(day: MiniCalendarDay): void {
    this.dateSelected.emit(day.date);
  }

  isSelected(day: MiniCalendarDay): boolean {
    return isSameDay(day.date, this.currentDate);
  }

  onCreateEvent(): void {
    this.createEventClicked.emit();
  }

  onToggleCalendar(calendarId: string): void {
    this.calendarVisibilityToggled.emit(calendarId);
  }
}
