import {
  Component,
  ChangeDetectionStrategy,
  Inject,
  OnInit,
  OnDestroy,
  ChangeDetectorRef,
} from '@angular/core';
/* STEP 8 / Phase 2.2: KeyboardManager 適用 */
import { KeyboardManagerService } from '../../../../shared/services/keyboard-manager.service';
import { Subscription } from 'rxjs';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MatDialogModule, MatDialogRef, MAT_DIALOG_DATA } from '@angular/material/dialog';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatDatepickerModule } from '@angular/material/datepicker';
import { MatNativeDateModule } from '@angular/material/core';
import { MatSelectModule } from '@angular/material/select';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatTooltipModule } from '@angular/material/tooltip';
import { CalendarEvent, EventGuest, EventReminder, RecurrenceRule, EventVisibility } from '../../models/event.model';
import { Calendar } from '../../models/calendar.model';
import { GuestPickerComponent } from '../guest-picker/guest-picker.component';
import { CalendarService } from '../../services/calendar.service';
import { format, setHours, setMinutes } from 'date-fns';

export interface EventEditorData {
  mode: 'create' | 'edit';
  event?: CalendarEvent;
  calendars: Calendar[];
  initialDate?: Date;
  initialStartTime?: string;
  initialEndTime?: string;
}

interface TimeOption {
  label: string;
  hour: number;
  minute: number;
}

@Component({
  selector: 'app-event-editor',
  standalone: true,
  imports: [
    CommonModule,
    FormsModule,
    MatDialogModule,
    MatButtonModule,
    MatIconModule,
    MatFormFieldModule,
    MatInputModule,
    MatDatepickerModule,
    MatNativeDateModule,
    MatSelectModule,
    MatCheckboxModule,
    MatTooltipModule,
    GuestPickerComponent,
  ],
  templateUrl: './event-editor.component.html',
  styleUrls: ['./event-editor.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class EventEditorComponent implements OnInit, OnDestroy {
  /* STEP 8 / Phase 2.2: KeyboardManager で SP キーボード時の dialog 高さを補正 */
  keyboardHeight = 0;
  private keyboardSub?: Subscription;
  mode: 'create' | 'edit' = 'create';
  calendars: Calendar[] = [];

  title = '';
  startDate: Date = new Date();
  endDate: Date = new Date();
  startTime = '09:00';
  endTime = '10:00';
  allDay = false;
  location = '';
  description = '';
  videoConferenceUrl = '';
  calendarId = 'cal-personal';
  visibility: EventVisibility = 'busy';
  guests: EventGuest[] = [];
  reminders: EventReminder[] = [{ method: 'popup', minutes: 15 }];
  recurrenceType = 'none';
  color = '';

  timeOptions: TimeOption[] = [];
  availabilitySlots: { hour: number; busy: boolean }[] = [];

  recurrenceOptions = [
    { value: 'none', label: '繰り返さない' },
    { value: 'daily', label: '毎日' },
    { value: 'weekdays', label: '平日' },
    { value: 'weekly', label: '毎週' },
    { value: 'monthly', label: '毎月' },
    { value: 'yearly', label: '毎年' },
  ];

  reminderOptions = [
    { value: 0, label: 'なし' },
    { value: 5, label: '5分前' },
    { value: 10, label: '10分前' },
    { value: 15, label: '15分前' },
    { value: 30, label: '30分前' },
    { value: 60, label: '1時間前' },
    { value: 120, label: '2時間前' },
    { value: 1440, label: '1日前' },
  ];

  visibilityOptions: { value: EventVisibility; label: string }[] = [
    { value: 'busy', label: '予定あり' },
    { value: 'free', label: '空き時間' },
    { value: 'tentative', label: '仮の予定' },
    { value: 'outOfOffice', label: '不在' },
  ];

  calendarColors = [
    '#ff9800', '#1976d2', '#4caf50', '#9c27b0', '#f44336',
    '#00bcd4', '#e91e63', '#795548', '#607d8b', '#ff5722',
  ];

  constructor(
    private dialogRef: MatDialogRef<EventEditorComponent>,
    @Inject(MAT_DIALOG_DATA) public data: EventEditorData,
    private calendarService: CalendarService,
    private cdr: ChangeDetectorRef,
    private keyboard: KeyboardManagerService,
  ) {
    /* STEP 8 / Phase 2.2: dialog 開いた直後から keyboard 監視 */
    this.keyboardSub = this.keyboard.keyboardHeight$.subscribe(h => {
      this.keyboardHeight = h;
      this.cdr.markForCheck();
    });
  }

  ngOnDestroy(): void {
    this.keyboardSub?.unsubscribe();
  }

  ngOnInit(): void {
    this.buildTimeOptions();
    this.mode = this.data.mode;
    this.calendars = this.data.calendars;

    /* ユーザー指示 (2026-04-21): 複製は Google Calendar と同じ挙動
       → 予定エディタが開き、元予定の値が全てプリフィルされた状態で
       新規作成される。このため create モードでも data.event があれば
       その値をコピー元としてプリフィルする。 */
    if (this.data.event && (this.mode === 'edit' || this.mode === 'create')) {
      const evt = this.data.event;
      this.title = evt.title;
      this.startDate = new Date(evt.start);
      this.endDate = new Date(evt.end);
      this.startTime = format(evt.start, 'HH:mm');
      this.endTime = format(evt.end, 'HH:mm');
      this.allDay = evt.allDay;
      this.location = evt.location || '';
      this.description = evt.description || '';
      this.videoConferenceUrl = evt.videoConferenceUrl || '';
      this.calendarId = evt.calendarId;
      this.visibility = evt.visibility;
      this.guests = evt.guests ? evt.guests.map(g => ({ ...g })) : [];
      this.reminders = evt.reminders ? evt.reminders.map(r => ({ ...r })) : [];
      this.color = evt.color || '';

      if (evt.recurrence) {
        if (evt.recurrence.frequency === 'daily' && evt.recurrence.byDay?.length === 5) {
          this.recurrenceType = 'weekdays';
        } else {
          this.recurrenceType = evt.recurrence.frequency;
        }
      }
    } else {
      if (this.data.initialDate) {
        this.startDate = new Date(this.data.initialDate);
        this.endDate = new Date(this.data.initialDate);
      }
      if (this.data.initialStartTime) {
        this.startTime = this.data.initialStartTime;
      }
      if (this.data.initialEndTime) {
        this.endTime = this.data.initialEndTime;
      }
    }

    this.loadAvailability();
  }

  private buildTimeOptions(): void {
    this.timeOptions = [];
    for (let h = 0; h < 24; h++) {
      for (let m = 0; m < 60; m += 15) {
        const hh = String(h).padStart(2, '0');
        const mm = String(m).padStart(2, '0');
        this.timeOptions.push({
          label: `${hh}:${mm}`,
          hour: h,
          minute: m,
        });
      }
    }
  }

  private loadAvailability(): void {
    this.calendarService.getAvailability(this.startDate).subscribe(slots => {
      this.availabilitySlots = slots.map(s => ({
        hour: s.start.getHours(),
        busy: s.busy,
      }));
      this.cdr.markForCheck();
    });
  }

  onStartDateChange(): void {
    if (this.endDate < this.startDate) {
      this.endDate = new Date(this.startDate);
    }
    this.loadAvailability();
  }

  onGuestsChange(guests: EventGuest[]): void {
    this.guests = guests;
  }

  addReminder(): void {
    this.reminders.push({ method: 'popup', minutes: 15 });
  }

  removeReminder(index: number): void {
    this.reminders.splice(index, 1);
  }

  addVideoConference(): void {
    this.videoConferenceUrl = 'https://meet.google.com/new-meeting-link';
  }

  selectColor(color: string): void {
    this.color = this.color === color ? '' : color;
  }

  onSave(): void {
    const [startH, startM] = this.startTime.split(':').map(Number);
    const [endH, endM] = this.endTime.split(':').map(Number);

    const start = this.allDay
      ? new Date(this.startDate.getFullYear(), this.startDate.getMonth(), this.startDate.getDate())
      : setMinutes(setHours(new Date(this.startDate), startH), startM);

    const end = this.allDay
      ? new Date(this.endDate.getFullYear(), this.endDate.getMonth(), this.endDate.getDate() + 1)
      : setMinutes(setHours(new Date(this.endDate), endH), endM);

    let recurrence: RecurrenceRule | undefined;
    switch (this.recurrenceType) {
      case 'daily':
        recurrence = { frequency: 'daily', interval: 1 };
        break;
      case 'weekdays':
        recurrence = { frequency: 'daily', interval: 1, byDay: ['MO', 'TU', 'WE', 'TH', 'FR'] };
        break;
      case 'weekly':
        recurrence = { frequency: 'weekly', interval: 1 };
        break;
      case 'monthly':
        recurrence = { frequency: 'monthly', interval: 1 };
        break;
      case 'yearly':
        recurrence = { frequency: 'yearly', interval: 1 };
        break;
    }

    const eventData: Partial<CalendarEvent> = {
      title: this.title || '(タイトルなし)',
      start,
      end,
      allDay: this.allDay,
      location: this.location || undefined,
      description: this.description || undefined,
      videoConferenceUrl: this.videoConferenceUrl || undefined,
      calendarId: this.calendarId,
      visibility: this.visibility,
      guests: this.guests,
      reminders: this.reminders,
      recurrence,
      color: this.color || undefined,
    };

    if (this.mode === 'edit' && this.data.event) {
      eventData.id = this.data.event.id;
    }

    this.dialogRef.close({ action: 'save', event: eventData });
  }

  onDelete(): void {
    this.dialogRef.close({ action: 'delete', event: this.data.event });
  }

  onCancel(): void {
    this.dialogRef.close({ action: 'cancel' });
  }

  getAvailabilityColor(hour: number): string {
    const slot = this.availabilitySlots.find(s => s.hour === hour);
    return slot?.busy ? '#f44336' : '#4caf50';
  }

  availabilityHours(): number[] {
    const hours = [];
    for (let h = 7; h <= 21; h++) {
      hours.push(h);
    }
    return hours;
  }
}
