import { Component, ChangeDetectionStrategy, Input, Output, EventEmitter } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';
import { MatButtonToggleModule } from '@angular/material/button-toggle';
import { CalendarView } from '../../models/calendar.model';
import {
  format,
  addMonths,
  addWeeks,
  addDays,
  subMonths,
  subWeeks,
  subDays,
  startOfWeek,
  endOfWeek,
} from 'date-fns';
import { ja } from 'date-fns/locale';

@Component({
  selector: 'app-calendar-header',
  standalone: true,
  imports: [CommonModule, FormsModule, MatButtonModule, MatIconModule, MatButtonToggleModule],
  templateUrl: './calendar-header.component.html',
  styleUrls: ['./calendar-header.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CalendarHeaderComponent {
  @Input({ required: true }) currentDate!: Date;
  @Input({ required: true }) currentView!: CalendarView;
  @Input() searchResults: any[] = [];
  @Output() dateChanged = new EventEmitter<Date>();
  @Output() viewChanged = new EventEmitter<CalendarView>();
  @Output() todayClicked = new EventEmitter<void>();
  @Output() eventSearch = new EventEmitter<string>();
  @Output() eventSelected = new EventEmitter<any>();

  /** カレンダーイベント検索: タイトル/詳細を対象にフィルタ */
  eventSearchQuery = '';
  searchFocused = false;

  onEventSearchChange(): void {
    this.eventSearch.emit(this.eventSearchQuery.trim());
  }
  clearEventSearch(): void {
    this.eventSearchQuery = '';
    this.eventSearch.emit('');
  }
  onSearchBlur(): void {
    // ドロップダウン内のクリックを処理するため少し待ってから閉じる
    setTimeout(() => { this.searchFocused = false; }, 150);
  }
  onSearchResultClick(event: any, e: MouseEvent): void {
    e.preventDefault();
    this.searchFocused = false;
    this.eventSelected.emit(event);
  }

  get dateDisplay(): string {
    switch (this.currentView) {
      case 'month':
        return format(this.currentDate, 'yyyy年M月', { locale: ja });
      case 'week7':
      case 'week5': {
        const weekStart = startOfWeek(this.currentDate, { weekStartsOn: 1 });
        const days = this.currentView === 'week7' ? 6 : 4;
        const weekEnd = addDays(weekStart, days);
        if (weekStart.getMonth() === weekEnd.getMonth()) {
          return format(weekStart, 'yyyy年M月', { locale: ja });
        }
        if (weekStart.getFullYear() === weekEnd.getFullYear()) {
          return `${format(weekStart, 'yyyy年M月', { locale: ja })} - ${format(weekEnd, 'M月', { locale: ja })}`;
        }
        return `${format(weekStart, 'yyyy年M月', { locale: ja })} - ${format(weekEnd, 'yyyy年M月', { locale: ja })}`;
      }
      case 'day3': {
        const dayEnd = addDays(this.currentDate, 2);
        if (this.currentDate.getMonth() === dayEnd.getMonth()) {
          return `${format(this.currentDate, 'yyyy年M月d日', { locale: ja })} - ${format(dayEnd, 'd日', { locale: ja })}`;
        }
        return `${format(this.currentDate, 'yyyy年M月d日', { locale: ja })} - ${format(dayEnd, 'M月d日', { locale: ja })}`;
      }
      case 'day1':
        return format(this.currentDate, 'yyyy年M月d日 (EEEE)', { locale: ja });
      default:
        return format(this.currentDate, 'yyyy年M月', { locale: ja });
    }
  }

  navigateBack(): void {
    let newDate: Date;
    switch (this.currentView) {
      case 'month':
        newDate = subMonths(this.currentDate, 1);
        break;
      case 'week7':
        newDate = subWeeks(this.currentDate, 1);
        break;
      case 'week5':
        newDate = subDays(this.currentDate, 5);
        break;
      case 'day3':
        newDate = subDays(this.currentDate, 3);
        break;
      case 'day1':
        newDate = subDays(this.currentDate, 1);
        break;
      default:
        newDate = subMonths(this.currentDate, 1);
    }
    this.dateChanged.emit(newDate);
  }

  navigateForward(): void {
    let newDate: Date;
    switch (this.currentView) {
      case 'month':
        newDate = addMonths(this.currentDate, 1);
        break;
      case 'week7':
        newDate = addWeeks(this.currentDate, 1);
        break;
      case 'week5':
        newDate = addDays(this.currentDate, 5);
        break;
      case 'day3':
        newDate = addDays(this.currentDate, 3);
        break;
      case 'day1':
        newDate = addDays(this.currentDate, 1);
        break;
      default:
        newDate = addMonths(this.currentDate, 1);
    }
    this.dateChanged.emit(newDate);
  }

  onViewChange(view: CalendarView): void {
    this.viewChanged.emit(view);
  }

  onTodayClick(): void {
    this.todayClicked.emit();
  }
}
